public class CartConfigService {
    private static volatile CartConfigService instance;
    private final int maxItemsPerCart;

    private CartConfigService() {
        // Private constructor prevents external instantiation
        this.maxItemsPerCart = 100;
    }

    public static CartConfigService getInstance() {
        if (instance == null) { // First check without lock for performance
            synchronized (CartConfigService.class) {
                if (instance == null) { // Second check inside lock
                    instance = new CartConfigService();
                }
            }
        }
        return instance;
    }

    public int getMaxItemsPerCart() {
        return maxItemsPerCart;
    }
}

@Service
public class CartService {
    private final ProductRepository productRepository;

    public CartService(ProductRepository productRepository) {
        this.productRepository = productRepository;
    }

    public Cart addItem(Long cartId, Long productId) {
        var product = productRepository.findById(productId);
        // Business logic to add product to cart
        return new Cart(cartId, List.of(product.orElseThrow()));
    }
}

@RestController
public class CartController {
    private final CartService cartService; // Same instance injected here

    public CartController(CartService cartService) {
        this.cartService = cartService;
    }
}

// CartService instance is created once by Spring and shared

// Problematic Singleton approach - hard to test
public class OrderProcessor {
    public void processOrder(Order order) {
        var logger = Logger.getInstance(); // Hidden dependency
        logger.log("Processing order: " + order.id());
        // Can't mock Logger in tests - it's a static call
    }
}

// Better Spring approach - testable with DI
@Service
public class OrderProcessor {
    private final Logger logger;

    public OrderProcessor(Logger logger) { // Explicit dependency
        this.logger = logger;
    }

    public void processOrder(Order order) {
        logger.log("Processing order: " + order.id());
        // Easy to inject mock Logger in unit tests
    }
}

public enum CartConfigService {
    INSTANCE; // Single enum constant is the singleton instance

    private final int maxItemsPerCart = 100;
    private final Map<String, String> discountRules;

    CartConfigService() {
        // Constructor runs once when enum is loaded
        discountRules = Map.of(
            "BULK10", "10% off on 10+ items",
            "FIRSTBUY", "15% off first purchase"
        );
    }

    public int getMaxItemsPerCart() {
        return maxItemsPerCart;
    }

    public Optional<String> getDiscountRule(String code) {
        return Optional.ofNullable(discountRules.get(code));
    }
}

// Usage: CartConfigService.INSTANCE.getMaxItemsPerCart()
